// HardDelete permanently removes a binary_key_badge from the database.
// Idempotent — returns nil if the primary key does not exist.
func (c *binaryKeyBadgeClient) HardDelete(ctx context.Context, pk BinaryKeyBadgePK, opts ...func(*CallOptions[BinaryKeyBadgeFieldOptions])) error {
	options := resolveCallOptions(opts)
	_, err := c.executeMutation(ctx, options.SkipHooks, &hook.MutationContext{
		Op: hook.OpHardDelete, Table: TableBinaryKeyBadges, Schema: "",
		PK: pk, CallOptions: options,
	}, func(ctx context.Context, m *hook.MutationContext) (any, error) {
		conn := database.Conn(ctx, c.querier)
		query, args := sql.BuildHardDelete(c.dialect, c.table, sql.HardDeleteOptions{
			Conditions: sql.BuildCompositePKConditions(c.dialect,
				[]string{"binary_key_id", "badge_code"},
				[]any{pk.BinaryKeyID, pk.BadgeCode}),
		})

		execResult, err := conn.Exec(ctx, query, args...)
		if err != nil {
			return nil, err
		}
		matched, err := execResult.RowsAffected()
		if err != nil {
			return nil, fmt.Errorf("rows affected: %w", err)
		}
		// A key that matched no row wrote nothing: it records no affected
		// key, so no cache entry is invalidated and no event is published.
		if matched > 0 {
			m.AffectedPKs = []any{pk}
		}
		return nil, nil
	})
	if err != nil {
		return fmt.Errorf("hard delete binary_key_badge: %w", err)
	}
	return nil
}

// HardDeleteMany permanently removes multiple binary_key_badges from the database.
func (c *binaryKeyBadgeClient) HardDeleteMany(ctx context.Context, pks []BinaryKeyBadgePK, opts ...func(*CallOptions[BinaryKeyBadgeFieldOptions])) error {
	options := resolveCallOptions(opts)
	_, err := c.executeMutation(ctx, options.SkipHooks, &hook.MutationContext{
		Op: hook.OpHardDeleteMany, Table: TableBinaryKeyBadges, Schema: "",
		Input: pks, CallOptions: options,
	}, func(ctx context.Context, m *hook.MutationContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		// The keys the sub-batches below write. A listed key that matches no
		// row stays out of it, so it records no affected key.
		written := make(map[string]struct{}, len(pks))

		// One statement per sub-batch of c.batchSize keys. A failing sub-batch
		// returns at once, and the sub-batches before it stay applied.
		for start := 0; start < len(pks); start += c.batchSize {
			end := min(start+c.batchSize, len(pks))
			pkValues := make([][]any, end-start)
			for i, pk := range pks[start:end] {
				pkValues[i] = []any{pk.BinaryKeyID, pk.BadgeCode}
			}
			hardConds := []sql.Condition{
				sql.BuildCompositePKBatchCondition(c.dialect, []string{"binary_key_id", "badge_code"}, pkValues),
			}

			// RETURNING the key columns names the rows this sub-batch wrote.
			query, args := sql.BuildHardDelete(c.dialect, c.table, sql.HardDeleteOptions{
				Conditions:       hardConds,
				ReturningColumns: []string{"binary_key_id", "badge_code"},
			})
			rows, err := conn.Query(ctx, query, args...)
			if err != nil {
				return nil, err
			}
			batchKeys := make(map[string]struct{}, end-start)
			for rows.Next() {
				var rowPK BinaryKeyBadgePK
				if err := rows.Scan(&rowPK.BinaryKeyID, &rowPK.BadgeCode); err != nil {
					rows.Close()
					return nil, fmt.Errorf("scan deleted binary_key_badge key: %w", err)
				}
				batchKeys[fmt.Sprintf("%#v", rowPK)] = struct{}{}
			}
			if err := rows.Err(); err != nil {
				rows.Close()
				return nil, err
			}
			rows.Close()
			c.recordWrittenKeys(written, pks[start:end], batchKeys)
		}

		// A listed key whose row this call did not write records no affected
		// key, so no cache entry is invalidated and no event is published for it.
		affectedPKs := make([]any, 0, len(pks))
		for _, key := range pks {
			if _, ok := written[fmt.Sprintf("%#v", key)]; ok {
				affectedPKs = append(affectedPKs, key)
			}
		}
		m.AffectedPKs = affectedPKs
		return nil, nil
	})
	if err != nil {
		return fmt.Errorf("hard delete many binary_key_badges: %w", err)
	}
	return nil
}

