// Connection returns a Relay-style cursor-paginated connection of binary_key_badges.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *binaryKeyBadgeClient) Connection(ctx context.Context, input ConnectionInput[BinaryKeyBadgeFilter], opts ...func(*CallOptions[BinaryKeyBadgeFieldOptions])) (*Connection[BinaryKeyBadge], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		return nil, fmt.Errorf("connection binary_key_badges: LockMode is unsupported on sqlite dialect")
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableBinaryKeyBadges, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[BinaryKeyBadgeFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeBinaryKeyBadgeCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeBinaryKeyBadgeCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		binaryKeyBadges, err := c.GetMany(ctx, &GetBinaryKeyBadgesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(binaryKeyBadges) > limit
		if hasMore {
			binaryKeyBadges = binaryKeyBadges[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(binaryKeyBadges)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[BinaryKeyBadge], len(binaryKeyBadges))
		for i, row := range binaryKeyBadges {
			cursor, err := encodeBinaryKeyBadgeCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[BinaryKeyBadge]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[BinaryKeyBadge]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection binary_key_badges: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*Connection[BinaryKeyBadge]), nil
}

// encodeBinaryKeyBadgeCursor encodes cursor key values as a base64 JSON string.
func encodeBinaryKeyBadgeCursor(keys []string, b *BinaryKeyBadge) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "binary_key_id":
			out["binary_key_id"] = b.BinaryKeyID
		case "badge_code":
			out["badge_code"] = b.BadgeCode
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode binary_key_badge cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeBinaryKeyBadgeCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeBinaryKeyBadgeCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row BinaryKeyBadge
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "binary_key_id":
			err = json.Unmarshal(raw[key], &row.BinaryKeyID)
			out[key] = row.BinaryKeyID
		case "badge_code":
			err = json.Unmarshal(raw[key], &row.BadgeCode)
			out[key] = row.BadgeCode
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

